45:   CONSTRAINT ck_m_student_student_name_kana_scalar CHECK (student_name_kana IS NULL OR LEN(CONVERT(nvarchar(max),student_name_kana) COLLATE Latin1_General_100_CS_AS_SC+N'#')-1<=18),
