49:   CONSTRAINT ck_m_student_address_line2_scalar CHECK (address_line2 IS NULL OR LEN(CONVERT(nvarchar(max),address_line2) COLLATE Latin1_General_100_CS_AS_SC+N'#')-1<=45),
50:   CONSTRAINT ck_m_student_emergency_contact_name_scalar CHECK (emergency_contact_name IS NULL OR LEN(CONVERT(nvarchar(max),emergency_contact_name) COLLATE Latin1_General_100_CS_AS_SC+N'#')-1<=8),
